<?php require __DIR__.'/includes/header.php'; $cid=currentCompanyId(); if(!$cid){$cid=(int)db()->query('SELECT id FROM companies ORDER BY id LIMIT 1')->fetchColumn();} $st=db()->prepare('SELECT * FROM companies WHERE id=?');$st->execute([$cid]);$c=$st->fetch();if(!$c)exit('Company not found'); checkCsrf(); if($_SERVER['REQUEST_METHOD']==='POST'){ $new=['name_ar'=>$_POST['name_ar'],'name_en'=>$_POST['name_en'],'email'=>$_POST['email'],'phone'=>$_POST['phone'],'contract_type'=>$_POST['contract_type']];pending('company',$cid,$cid,$c,$new);audit('requested_update','company',$cid);$msg=t('pending');} ?>
<div class="title-row"><h1><?=t('company_profile')?></h1><span class="badge pending"><?=t('company_only')?></span></div><?php if(!empty($msg)):?><div class="alert success">✓ <?=$msg?></div><?php endif;?><section class="card"><div class="profile-head"><div class="avatar">🏢</div><div><h2><?=e($c['name_'.$lang]?:$c['name_en'])?></h2><p><?=e($c['company_code'])?></p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><label><?=t('name_ar')?><input name="name_ar" value="<?=e($c['name_ar'])?>"></label><label><?=t('name_en')?><input name="name_en" value="<?=e($c['name_en'])?>"></label><label><?=t('email')?><input name="email" value="<?=e($c['email'])?>"></label><label><?=t('phone')?><input name="phone" value="<?=e($c['phone'])?>"></label><label><?=t('company')?><input name="contract_type" value="<?=e($c['contract_type'])?>"></label><div class="actions"><button class="btn primary"><?=t('request_update')?></button></div></form></section><?php require __DIR__.'/includes/footer.php'; ?>
